(arg) {
    if (arg === 0)
        return;
    let i = 0;
    let digits = "";
    let k = 0n;
    let k1 = 1n;
    let a = 0n;
    let d = 1n;
    let m = 0n;
    let n = 1n;
    let t = 0n;
    let u = 1n;
    while (true) {
        k += 1n;
        k1 += 2n;
        t = n << 1n;
        n *= k;
        a += t;
        a *= k1;
        d *= k1;
        if (a > n) {
            m = n * 3n + a;
            t = m / d;
            u = (m + n) / d;
            if (t === u) {
                digits += t.toString();
                i += 1;
                let last = i >= arg;
                if (i % 10 == 0 || last) {
                    console.log(digits.padEnd(10, " ") + '\x5ct:' + i);
                    digits = "";
                }
                if (last)
                    break;
                a = (a - d * t) * 10n;
                n = n * 10n;
            }
        }
    }
}


